#!/usr/bin/env python3
import os, sys
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

def esc(s):
    return s.replace("\\", "\\\\").replace("'", "\\'")

def build_lesson(prefix, slug, vi, en, sents, cult, tip, vocab, dial, exs):
    parts = []
    parts.append("  {")
    parts.append('    id: "' + prefix + "_" + slug + '",')
    parts.append('    category: "' + slug + '" as any,')
    parts.append('    title_vi: "' + esc(vi) + '",')
    parts.append('    title_en: "' + esc(en) + '",')
    
    # sentences
    parts.append("    sentences: [")
    sent_lines = []
    for s_en, s_vi, focus in sents:
        f = ", ".join("'" + esc(x) + "'" for x in focus)
        sent_lines.append("      { en: '" + esc(s_en) + "', vi: '" + esc(s_vi) + "', pronunciation_focus: [" + f + "] }")
    parts.append(",\n".join(sent_lines))
    parts.append("    ],")
    
    parts.append('    cultural_notes_vi: "' + esc(cult) + '",')
    parts.append('    tip_advice_vi: "' + esc(tip) + '",')
    
    # vocab
    parts.append("    vocabulary: [")
    v_lines = []
    for w, en_text, vi_text, pos, pron in vocab:
        v_lines.append("      { word: '" + esc(w) + "', en: '" + esc(en_text) + "', vi: '" + esc(vi_text) + "', pos: '" + esc(pos) + "', pronunciation_vi: '" + esc(pron) + "' }")
    parts.append(",\n".join(v_lines))
    parts.append("    ],")
    
    # dialogue
    parts.append("    dialogue: [")
    d_lines = []
    for sp, text, vi_text in dial:
        d_lines.append("      { speaker: '" + esc(sp) + "', text: '" + esc(text) + "', vi: '" + esc(vi_text) + "' }")
    parts.append(",\n".join(d_lines))
    parts.append("    ],")
    
    # exercises
    parts.append("    exercises: [")
    ex_parts = []
    for ex in exs:
        items = []
        for it in ex["items"]:
            p = esc(it["prompt"])
            a = esc(it["answer"])
            if "options" in it and it["options"]:
                o = ", ".join("'" + esc(x) + "'" for x in it["options"])
                items.append("        { prompt: '" + p + "', answer: '" + a + "', options: [" + o + "] }")
            else:
                items.append("        { prompt: '" + p + "', answer: '" + a + "' }")
        pf = ", ".join("'" + esc(x) + "'" for x in ex["pronunciation_focus"])
        ep = "      {\n"
        ep += '        type: "' + ex["type"] + '",\n'
        ep += '        instruction_vi: "' + esc(ex["instruction_vi"]) + '",\n'
        ep += "        pronunciation_focus: [" + pf + "],\n"
        ep += "        items: [\n" + ",\n".join(items) + "\n        ],\n"
        ep += "      }"
        ex_parts.append(ep)
    parts.append(",\n".join(ex_parts))
    parts.append("    ],")
    parts.append("  }")
    return "\n".join(parts)

def std_exs(slug, voc, trans_sents):
    v = voc
    s = trans_sents
    e1 = {"type":"fill_blank","instruction_vi":"\u0110i\u1ec1n t\u1eeb \u0111\u00fang:","pronunciation_focus":[slug],"items":[{"prompt":v[0][2]+" \u2192 ___","answer":v[0][0]},{"prompt":v[1][2]+" \u2192 ___","answer":v[1][0]},{"prompt":v[2][2]+" \u2192 ___","answer":v[2][0]}]}
    e2 = {"type":"matching","instruction_vi":"N\u1ed1i t\u1eeb v\u1edbi ngh\u0129a:","pronunciation_focus":[slug],"items":[{"prompt":v[3][0],"answer":v[3][2]},{"prompt":v[4][0],"answer":v[4][2]},{"prompt":v[5][0],"answer":v[5][2]},{"prompt":v[6][0],"answer":v[6][2]}]}
    e3 = {"type":"translation","instruction_vi":"D\u1ecbch:","pronunciation_focus":[slug],"items":[{"prompt":s[0][1],"answer":s[0][0]},{"prompt":s[1][1],"answer":s[1][0]},{"prompt":s[2][1],"answer":s[2][0]}]}
    return [e1, e2, e3]

