    return [("A","Bonjour, j'ai une question sur "+topic+".","Ch\u00e0o, t\u00f4i c\u00f3 c\u00e2u h\u1ecfi v\u1ec1 "+topic+"."),("B","Bien s\u00fbr, que voulez-vous savoir ?","V\u00e2ng, b\u1ea1n mu\u1ed1n bi\u1ebft g\u00ec?"),("A","Pouvez-vous m'expliquer ?","Gi\u1ea3i th\u00edch \u0111\u01b0\u1ee3c kh\u00f4ng?"),("B","Avec plaisir. Voici l'essentiel.","Vui l\u00f2ng. \u0110\u00e2y l\u00e0 \u0111i\u1ec3m ch\u00ednh.")]

